{"file_path":"src/policies.js","content":"/**
 * A token bucket. Tokens are tracked internally scaled by `per` so that the
 * fractional refill per tick (`refill` tokens for every `per` ticks) is
 * represented exactly as an integer, never rounded.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  #state(key, tick) {
    let s = this.states.get(key)
    if (!s) {
      s = { scaled: this.capacity * this.per, lastTick: tick }
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const s = this.#state(key, tick)
    const elapsed = tick - s.lastTick
    if (elapsed > 0n) {
      const capScaled = this.capacity * this.per
      s.scaled += this.refill * elapsed
      if (s.scaled > capScaled) s.scaled = capScaled
      s.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).scaled >= this.per
  }

  record(key) {
    this.states.get(key).scaled -= this.per
  }
}

/** A sliding window that remembers the ticks of the requests it recorded for each key. */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let s = this.states.get(key)
    if (!s) {
      s = []
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const arr = this.#state(key)
    const threshold = tick - this.span
    while (arr.length && arr[0] <= threshold) arr.shift()
  }

  allows(key) {
    return this.#state(key).length < this.limit
  }

  record(key, tick) {
    this.#state(key).push(tick)
  }
}
"}

