{"file_path":"src/parser.js","content":"import { ParseError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function splitLines(text) {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function validateField(name, str, min, minDisplay, line) {
  if (!INT_RE.test(str) || BigInt(str) < min) {
    throw new ParseError(line, `${name} must be an integer of at least ${minDisplay}`)
  }
  return BigInt(str)
}

function validateName(kind, value, line) {
  if (!NAME_RE.test(value)) throw new ParseError(line, `invalid ${kind} ${value}`)
}

/**
 * Parses a limiter file into its declarations. Throws a ParseError naming the
 * first line that fails, in the order the specification lists its checks.
 */
export function parseLimiterFile(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let sawEvent = false
  let lastTick = null

  const lines = splitLines(text)
  for (let i = 0; i < lines.length; i++) {
    const line = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'bucket' || word === 'window' || word === 'route') {
      if (sawEvent) throw new ParseError(line, 'declarations must come before the first event')
    }

    if (word === 'bucket') {
      if (tokens.length !== 5) throw new ParseError(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityStr, refillStr, perStr] = tokens
      validateName('policy name', name, line)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      const capacity = validateField('capacity', capacityStr, 1n, 1, line)
      const refill = validateField('refill', refillStr, 0n, 0, line)
      const per = validateField('per', perStr, 1n, 1, line)
      policies.set(name, { type: 'bucket', capacity, refill, per })
    } else if (word === 'window') {
      if (tokens.length !== 4) throw new ParseError(line, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = tokens
      validateName('policy name', name, line)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      const limit = validateField('limit', limitStr, 0n, 0, line)
      const span = validateField('span', spanStr, 1n, 1, line)
      policies.set(name, { type: 'window', limit, span })
    } else if (word === 'route') {
      if (tokens.length < 3) throw new ParseError(line, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      validateName('route prefix', prefix, line)
      if (routes.has(prefix)) throw new ParseError(line, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new ParseError(line, `unknown policy ${name}`)
      }
      routes.set(prefix, policyNames)
    } else if (word === 'event') {
      if (tokens.length !== 3) throw new ParseError(line, 'expected event <tick> <key>')
      const [, tickStr, key] = tokens
      const tick = validateField('tick', tickStr, 0n, 0, line)
      validateName('key', key, line)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(line, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      sawEvent = true
      events.push({ tick, key })
    } else {
      throw new ParseError(line, `unknown directive ${word}`)
    }
  }

  return { policies, routes, events }
}
"}

