{"file_path":"src/simulate.js","content":"import { TokenBucket, SlidingWindow } from './policies.js'

function buildInstance(def) {
  return def.type === 'bucket'
    ? new TokenBucket(def.capacity, def.refill, def.per)
    : new SlidingWindow(def.limit, def.span)
}

function longestRoute(routes, key) {
  let best = null
  for (const [prefix, names] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.prefix.length)) {
      best = { prefix, names }
    }
  }
  return best ? best.names : null
}

/**
 * Replays the parsed events in order, returning one verdict per event and the
 * allowed/denied totals per key.
 */
export function simulate({ policies, routes, events }) {
